INSERT INTO "curriculum_chunks" ("id", "doc_id", "country", "grade", "subject", "chapter", "page_range", "chunk_index", "content", "content_normalized", "keywords", "embedding", "updated_at") VALUES ('826e4bff-8753-46e1-99f4-7a0ecc9b58f4', 'aeab0878-dd6e-4b44-8632-d633418ac70e', 'sudan', 'grade12', 'physics', 'الفصل الثاني', '13-16', 7, 'دوران الجسم ، فستجد أن الجسم ينطلق مبتعداً في نفس اتجاه
السرعة المماسية في تلك اللحظة ، ويسير في ذلك الاتجاه كما لو أن الجسم كان
يحاول طول الوقت السير في خط مستقيم، ولكن كان الخيط يمنعه ويجبره على
السير في دائرة نصف قطرها طول الخيط .
أي أن الخيط كان يمد الجسم بقوة تشده إلى مركز الدائرة ليدور حولها
وهذه القوة هي التي يحبسها الشخص الممسك بالخيط في صورة شد في الخيط
يزيد كلما زادت سرعة الجسم .
إذا لكي يدور أي جسم في دائرة لا بد من وجود قوة تشده أو تربطه مع
مركز الدائرة وتسمى هذه القوة : قوة الجذب المركزية .
وعلى ذلك في التجربة السابقة فالخيط هو الذي يمد الجسم بقوة الجذب
المركزية وتظهر هذه القوة في صورة شد في الخيط إلى الخارج وتعادل قيمة
هذا الشد قيمة قوة الجذب المركزية (اتجاه الشد عكس اتجاه القوة كما في شكل
(1-6 ب)) .
لاحظ أننا إذا أوقفنا الجسم عن الدوران يختفي الشد ويسترخي الخيط
وبالتالي تختفي هذه القوة لأن وجودها مربوط بوجود الدوران .

20
2-3) قوانين الحركة الدائرية :
1/ الزمن الدوري :
هو الزمن اللازم لكي يكمل الجسم الذي يدور في دائرة دورة كاملة
ويرمز بالرمز ز
فالأرض مثلاً تكمل دورة كاملة حول الشمس في 365 يوماً وربع اليوم
تقريباً (بالضبط 365 يوم و 6 ساعات و 9 دقائق و 59 ثانية).إذا فالزمن الدوري
لدوران الأرض حول الشمس هو هذا المقدار محسوباً بالثانية. وعليه فالزمن
الدوري للأرض:
